with recursive nodes as materialized(select r.domain,r.id,r.parent_id from public.ref_code r where api.is_ref_code_taxonomy_domain(r.domain)),
 walk(domain,ancestor_id,descendant_id,depth,visited,cycle) as(select domain,id,id,0,array[id],false from nodes union all select w.domain,w.ancestor_id,c.id,w.depth+1,w.visited||c.id,c.id=any(w.visited)from walk w join nodes c on c.domain=w.domain and c.parent_id=w.descendant_id where not w.cycle and w.depth<100),
 expected as materialized(select domain,ancestor_id,descendant_id,depth from walk where not cycle),
 actual as materialized(select domain,ancestor_id,descendant_id,depth from public.ref_code_taxonomy_closure) select jsonb_build_object('captured_at',statement_timestamp(),
'release_id',(select current_release_id from thesaurus.instance),
'closure',jsonb_build_object('expected_rows',(select count(*)from expected),
'actual_rows',(select count(*)from actual),
'missing_rows',(select count(*)from(select * from expected except select * from actual)x),
'unexpected_rows',(select count(*)from(select * from actual except select * from expected)x),
'cycles',(select count(*)from walk where cycle),
'depth_limit_hits',(select count(*)from walk where depth=100)),
'crosswalk',jsonb_build_object('rows',(select count(*)from public.ref_interop_crosswalk),
'taxonomy_rows',(select count(*)from public.ref_interop_crosswalk where taxonomy_code is not null),
'missing_taxonomy_targets',(select count(*)from public.ref_interop_crosswalk x where x.taxonomy_code is not null and not exists(select 1 from public.ref_code r where r.domain=x.taxonomy_domain and r.code=x.taxonomy_code))),
'catalog_registry',jsonb_build_object('registry_rows',(select count(*)from public.ref_catalog_registry),
'discovered_keys',(select count(*)from internal.v_ref_catalog),
'registry_not_discovered',(select count(*)from public.ref_catalog_registry r where not exists(select 1 from internal.v_ref_catalog v where v.catalog_key=r.catalog_key)),
'discovered_without_registry',(select count(*)from internal.v_ref_catalog v where not exists(select 1 from public.ref_catalog_registry r where v.catalog_key=r.catalog_key))),
'facet_registry',jsonb_build_object('rows',(select count(*)from public.ref_facet_registry),
'missing_physical_tables',(select count(*)from public.ref_facet_registry r where to_regclass(format('public.%I',r.facet_table))is null),
'missing_object_id_columns',(select count(*)from public.ref_facet_registry r where not exists(select 1 from pg_attribute a where a.attrelid=to_regclass(format('public.%I',r.facet_table))and a.attname=r.object_id_column and a.attnum>0 and not a.attisdropped)))) semantic_integrity;
